import assert from 'node:assert/strict';
import {createTravel} from '../src/studies/portal-travel.mjs';
import {STOPS,DOORS,routeX,roomAt} from '../src/studies/portal-scene.mjs';

const results=[];
function journey(from,to,hz){
  const travel=createTravel(from),crossed=[];
  travel.go(to);
  for(let frame=0;travel.moving&&frame<hz*45;frame++){
    const before=travel.z;travel.step(1/hz);
    assert.ok(Math.abs(travel.z-before)<=2.601/hz,'camera displacement respects walking speed');
    assert.ok(travel.z>=Math.min(from,to)-1e-6&&travel.z<=Math.max(from,to)+1e-6,'camera stays in connected corridor');
    for(const door of DOORS)if((before-door)*(travel.z-door)<=0&&!crossed.includes(door)){
      crossed.push(door);
      assert.ok(Math.abs(routeX(travel.z)-routeX(door))+.09<1.68,'eye and pointer margin fit the clear aperture');
    }
  }
  assert.equal(travel.z,to,'arrives exactly');assert.equal(travel.velocity,0,'stops at destination');
  return crossed;
}
for(const hz of [20,60,144]){
  assert.deepEqual(journey(STOPS[0],STOPS[3],hz),DOORS);
  assert.deepEqual(journey(STOPS[3],STOPS[0],hz),[...DOORS].reverse());
  results.push(`forward and return: ${hz} Hz, three apertures crossed`);
}
const paused=createTravel(STOPS[0]);paused.go(STOPS[1]);paused.step(1);
const frozen={z:paused.z,velocity:paused.velocity};
paused.go(STOPS[3]);for(let i=0;i<100;i++)paused.step(0);
assert.equal(paused.z,frozen.z);assert.equal(paused.velocity,frozen.velocity);
paused.go(STOPS[0]);assert.equal(paused.z,frozen.z,'retarget does not relocate camera');
for(let i=0;i<1200;i++)paused.step(1/60);
assert.equal(paused.z,STOPS[0]);
results.push('pause, interrupted selection and reverse travel preserve position');
for(const [i,door] of DOORS.entries()){
  assert.equal(roomAt(door+.001),i);assert.equal(roomAt(door-.001),i+1);
}
results.push('chapter changes at the physical door planes');
console.log(JSON.stringify({passed:true,checks:results},null,2));

import {clamp} from './math.mjs';
import {asset,image,range,button} from './core.mjs';
import {createArchitecture,STOPS,DOORS,routeX,roomAt} from './portal-scene.mjs';
import {createTravel} from './portal-travel.mjs';

export async function create(stage,controls) {
  const chapters=JSON.parse(document.querySelector('#portal-chapters').textContent);
  const art=await Promise.all(chapters.map(chapter=>image(asset(chapter.image))));
  const architecture=createArchitecture(art),travel=createTravel(STOPS[0]);
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  const theater=document.querySelector('.theater'),hero=document.querySelector('.hero-copy');
  const eyebrow=hero.querySelector('.eyebrow'),heading=hero.querySelector('h1'),body=hero.querySelector('p');
  const stageTag=document.querySelector('.stage-tag'),coordinate=document.querySelector('.study-coordinate');
  const telemetry=document.querySelector('.telemetry');
  let chapterIndex=0,destination=0,yaw=0,yawTarget=0,auto=false,chapterTime=0,direction=1;
  const holdSeconds=8;

  const edition=document.createElement('div');edition.className='portal-edition';
  edition.innerHTML='<span>彼处 <b>ELSEWHERE</b></span><small>空间声音手记 / CONCEPT JOURNAL</small>';
  theater.append(edition);
  const folio=document.createElement('aside');folio.className='portal-folio';
  folio.setAttribute('aria-label','本章产品札记');
  folio.innerHTML='<div class="portal-folio-top"><span></span><b></b></div><h2></h2><p></p><div class="portal-tags"></div>';
  theater.append(folio);
  const note=document.createElement('div');note.className='portal-note';
  note.innerHTML='<span>FROM THE FIELD</span><p></p><small></small>';theater.append(note);
  const chapterMark=document.createElement('div');chapterMark.className='portal-chapter-mark';
  chapterMark.setAttribute('aria-hidden','true');theater.append(chapterMark);
  hero.setAttribute('aria-live','polite');hero.setAttribute('aria-atomic','true');
  const route=document.createElement('div');route.className='portal-route';route.setAttribute('aria-label','展室行走路线');
  route.innerHTML='<span>01</span><i><b></b><em></em><em></em><em></em></i><span>04</span><output></output>';theater.append(route);
  for(const [i,mark] of [...route.querySelectorAll('em')].entries())mark.style.left=((STOPS[0]-DOORS[i])/(STOPS[0]-STOPS[3])*100)+'%';

  const slider=range(controls,'穿越进度',0,100,0,.1,v=>{
    auto=false;chapterTime=0;
    travel.seek(STOPS[0]+(STOPS[3]-STOPS[0])*v/100);destination=roomAt(travel.z);stage.dirty=true;
  });
  button(controls,'穿过下一扇门',()=>select((destination+1)%4));
  const turnButton=button(controls,'回头看',()=>{yawTarget=yawTarget===0?Math.PI:0;auto=false;stage.dirty=true;});
  const roamButton=button(controls,'自动漫游',()=>{auto=!auto;chapterTime=0;if(auto)stage.setPlaying(true);stage.dirty=true;});

  function writeCopy() {
    const chapter=chapters[chapterIndex],number=String(chapterIndex+1).padStart(2,'0');
    document.body.style.setProperty('--accent',chapter.accent);
    document.body.dataset.chapter=chapter.id;
    hero.dataset.chapter=folio.dataset.chapter=chapter.id;
    eyebrow.replaceChildren();
    const name=document.createElement('span');name.textContent=chapter.english;
    const rule=document.createElement('i'),index=document.createElement('span');index.textContent=number+' / 04';
    eyebrow.append(name,rule,index);
    [...heading.children].forEach((line,i)=>line.textContent=chapter.headline[i]);
    body.textContent=chapter.body;
    document.querySelector('#interact > span').textContent=chapter.action;
    stageTag.replaceChildren();
    const dash=document.createElement('span'),tag=document.createElement('b');tag.textContent=chapter.kicker;
    stageTag.append(dash,document.createTextNode('ELSEWHERE / FIELD JOURNAL'),tag);
    coordinate.querySelector('span').textContent=chapter.coordinate;
    coordinate.querySelector('b').textContent=chapter.time;
    folio.querySelector('.portal-folio-top span').textContent='PRODUCT NOTE / '+number;
    folio.querySelector('.portal-folio-top b').textContent=chapter.location;
    folio.querySelector('h2').textContent=chapter.feature;
    folio.querySelector('p').textContent=chapter.detail;
    const tags=folio.querySelector('.portal-tags');tags.replaceChildren();
    for(const text of chapter.tags){const tag=document.createElement('span');tag.textContent=text;tags.append(tag);}
    note.querySelector('p').textContent=chapter.note;
    note.querySelector('small').textContent=chapter.location+' / '+chapter.time;
    chapterMark.textContent=number;
    telemetry.querySelector('.telemetry-bottom span').textContent=chapter.english;
    telemetry.setAttribute('aria-label','当前手记');
    roamButton.setAttribute('aria-pressed',String(auto));
  }

  function select(index,{continueRoam=false}={}) {
    destination=index;auto=continueRoam;chapterTime=0;
    // The existing pose is the start of every trip, including an interrupted trip.
    travel.go(STOPS[index]);
    yawTarget=STOPS[index]>travel.z+.1?Math.PI:0;
    if(reduced.matches){travel.seek(STOPS[index]);yaw=yawTarget;}
    stage.dirty=true;
  }
  function reset(){travel.seek(STOPS[0]);destination=0;chapterIndex=0;yaw=yawTarget=0;auto=false;chapterTime=0;direction=1;slider.value=0;writeCopy();stage.dirty=true;}
  const scenes={label:'THE FIELD ATLAS',kind:'JOURNAL',items:chapters.map((chapter,index)=>({
    ...chapter,apply:()=>select(index),active:()=>chapterIndex===index,
  }))};
  writeCopy();
  return {
    scenes,reset,interact:()=>select((destination+1)%chapters.length),
    key(key){
      auto=false;chapterTime=0;
      if(key==='ArrowUp'||key==='ArrowDown')travel.go(clamp(travel.target+(key==='ArrowUp'?-1:1)*Math.cos(yawTarget)*1.2,STOPS[3],STOPS[0]));
      if(key==='ArrowLeft')yawTarget-=.15;
      if(key==='ArrowRight')yawTarget+=.15;
      destination=roomAt(travel.target);
    },
    render(dt){
      // Turning finishes before returning along the same physical corridor.
      yaw+=clamp(yawTarget-yaw,-dt*.85,dt*.85);
      const turning=Math.abs(yawTarget-yaw)>.12;
      travel.step(turning?0:dt);
      if(auto&&dt&&!travel.moving&&!turning){
        chapterTime+=dt;
        if(chapterTime>=holdSeconds){
          if(destination===3)direction=-1;if(destination===0)direction=1;
          select(destination+direction,{continueRoam:true});
        }
      }
      const current=roomAt(travel.z);
      if(current!==chapterIndex){chapterIndex=current;writeCopy();}
      const progress=(STOPS[0]-travel.z)/(STOPS[0]-STOPS[3]);
      slider.value=String((progress*100).toFixed(1));
      const {ctx,width:w,height:h,pointer:p}=stage;
      const eye=[routeX(travel.z)+(reduced.matches?0:(p.x-.5)*.18),2.22+(reduced.matches?0:(p.y-.5)*-.08),travel.z];
      architecture.render(stage.canvas.width,stage.canvas.height,eye,yaw);
      ctx.drawImage(architecture.canvas,0,0,w,h);
      theater.dataset.travelling=String(travel.moving||turning);
      route.style.setProperty('--travel',String(progress));
      route.querySelector('output').textContent=(travel.moving?'行走至 '+chapters[destination].title:chapters[chapterIndex].title)+' / '+(STOPS[0]-travel.z).toFixed(1)+' m';
      roamButton.setAttribute('aria-pressed',String(auto));turnButton.setAttribute('aria-pressed',String(Math.cos(yaw)<0));
      // DOM telemetry is also useful when comparing reproducible threshold frames.
      stage.canvas.dataset.cameraZ=travel.z.toFixed(3);
      stage.canvas.dataset.room=String(chapterIndex+1);
      stage.canvas.dataset.travel=travel.moving?'moving':'settled';
      stage.canvas.dataset.renderer='webgl-depth';
      stage.status(chapters[chapterIndex].location+' · Z '+travel.z.toFixed(2)+' m'+(!stage.playing&&(travel.moving||turning)?' · 待继续':turning?' · 转身中':travel.moving?' · 穿门中':auto?' · 漫游中':' · 已抵达'));
    },
    inspect:()=>({progress:(STOPS[0]-travel.z)/(STOPS[0]-STOPS[3]),z:travel.z,targetZ:travel.target,velocity:travel.velocity,
      chapter:chapters[chapterIndex].id,chapterIndex,destination,yaw,auto,chapterTime,
      renderer:'webgl-depth',rooms:4,doorPlanes:DOORS,triangles:architecture.triangles,texturesLoaded:art.length,holdSeconds}),
    dispose:()=>architecture.dispose(),
  };
}

import {box,cross,sub,unit} from './math.mjs';

// All four rooms share these world coordinates, including the walkable openings.
export const STOPS=[5.8,-5.4,-15.4,-25.4];
export const DOORS=[0,-10,-20];
export const routeX=z=>.42*Math.sin((5.8-z)*.16);
export const roomAt=z=>DOORS.filter(door=>z<door).length;

const vertex=`
attribute vec3 position, normal, color;
attribute vec2 uv;
attribute float material;
uniform vec3 eye;
uniform float yaw, aspect, lens, offset;
varying vec3 vPosition,vNormal,vColor;
varying vec2 vUV;
varying float vMaterial,vDepth;
void main(){
  vec3 p=position-eye;
  float x=cos(yaw)*p.x+sin(yaw)*p.z;
  float z=sin(yaw)*p.x-cos(yaw)*p.z;
  gl_Position=vec4(x*lens/aspect+offset*z,p.y*lens,1.002*z-.1001,z);
  vPosition=position;vNormal=normal;vColor=color;vUV=uv;vMaterial=material;vDepth=z;
}`;
const fragment=`
precision highp float;
varying vec3 vPosition,vNormal,vColor;
varying vec2 vUV;
varying float vMaterial,vDepth;
uniform sampler2D artwork;
uniform float textured;
float hash(vec3 p){return fract(sin(dot(p,vec3(127.1,311.7,74.7)))*43758.5453);}
float noise(vec2 p){
  vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);
  return mix(mix(hash(vec3(i,0.)),hash(vec3(i+vec2(1.,0.),0.)),f.x),
             mix(hash(vec3(i+vec2(0.,1.),0.)),hash(vec3(i+1.,0.)),f.x),f.y);
}
void main(){
  vec3 n=normalize(vNormal),p=vPosition;
  float light=.45+.36*abs(dot(n,normalize(vec3(-.4,.9,.3))));
  float grain=hash(floor(p*95.))*.075;
  float band=.5+.5*sin(p.y*19.+sin(p.z*2.)*.6);
  vec3 c=vColor*(light+grain);
  if(vMaterial>0.5 && vMaterial<1.5){
    vec2 surface=vec2(p.x+p.z,p.y+p.z*.37);
    float patina=noise(surface*3.)*.65+noise(surface*11.)*.35;
    c=mix(c,c*vec3(.57,.92,.85),smoothstep(.40,.72,patina)*.42);
    c+=vec3(.14,.11,.055)*pow(max(0.,n.y),2.);
  }
  if(vMaterial>1.5 && vMaterial<2.5)c=vColor*(.74+band*.07+grain);
  if(vMaterial>2.5)c=vColor;
  // Soft pools from the continuous ceiling slots and lit door reveals.
  float z=min(min(abs(p.z),abs(p.z+10.)),abs(p.z+20.));
  float pool=exp(-z*z*.22)*exp(-p.x*p.x*.14);
  c+=vColor*pool*.25;
  c*=.78+.22*smoothstep(0.,.9,p.y+.12);
  if(textured>.5)c=texture2D(artwork,vUV).rgb*.83;
  float fog=1.-exp(-max(0.,vDepth)*.010);
  c=mix(c,vec3(.055,.092,.10),fog);
  gl_FragColor=vec4(c,1.);
}`;

export function createArchitecture(art){
  const canvas=document.createElement('canvas');
  const gl=canvas.getContext('webgl',{alpha:false,antialias:true,preserveDrawingBuffer:false});
  if(!gl)throw new Error('此浏览器需要开启 WebGL 才能游览展室');
  const shader=(type,source)=>{const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw new Error(gl.getShaderInfoLog(s));return s;};
  const program=gl.createProgram(),shaders=[shader(gl.VERTEX_SHADER,vertex),shader(gl.FRAGMENT_SHADER,fragment)];
  shaders.forEach(s=>gl.attachShader(program,s));gl.linkProgram(program);
  if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw new Error(gl.getProgramInfoLog(program));
  gl.useProgram(program);gl.enable(gl.DEPTH_TEST);gl.clearColor(.035,.064,.075,1);
  const uniforms=Object.fromEntries(['eye','yaw','aspect','lens','offset','artwork','textured'].map(n=>[n,gl.getUniformLocation(program,n)]));
  const attributes=Object.fromEntries(['position','normal','color','uv','material'].map(n=>[n,gl.getAttribLocation(program,n)]));
  const batches=[],solid=[];
  const rgb=hex=>[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255);
  function quad(points,color,material=0,vertices=solid){
    const normal=unit(cross(sub(points[1],points[0]),sub(points[2],points[0]))),c=rgb(color);
    const uv=[[0,0],[1,0],[1,1],[0,1]];
    for(const i of [0,1,2,0,2,3])vertices.push(...points[i],...normal,...c,...uv[i],material);
  }
  function cuboid(center,size,color,material=0){for(const side of box(center,size,color))quad(side.points,color,material);}
  function panel(points,texture){const vertices=[];quad(points,'#ffffff',3,vertices);batches.push({vertices,texture});}
  const palettes=[
    {wall:'#466361',floor:'#798783',ceiling:'#2c4244',accent:'#c5b27f',water:'#37656b'},
    {wall:'#576454',floor:'#7b8370',ceiling:'#374538',accent:'#c6c49a',water:'#495e44'},
    {wall:'#414f65',floor:'#677888',ceiling:'#222f46',accent:'#b1bad5',water:'#3b536d'},
    {wall:'#677f85',floor:'#8c9b9c',ceiling:'#465d66',accent:'#d1dcd7',water:'#6c9faa'},
  ];
  for(let i=0;i<4;i++){
    const front=10-i*10,back=-i*10,p=palettes[i],mid=(front+back)/2;
    // Slab joints, side pools and wall bays provide stable parallax landmarks.
    for(let z=back;z<front;z+=1.25)for(let x=-7;x<7;x+=1.4)
      cuboid([x+.7,-.09,z+.625],[1.385,.18,1.235],p.floor);
    cuboid([-7.12,3.5,mid],[.24,7,10],p.wall);
    cuboid([7.12,3.5,mid],[.24,7,10],p.wall);
    cuboid([0,7.1,mid],[14,.2,10],p.ceiling);
    for(const side of [-1,1]){
      cuboid([side*5.4,.025,mid],[2.1,.05,8.4],p.water,2);
      cuboid([side*4.25,.14,mid],[.12,.28,8.4],p.accent,1);
      cuboid([side*6.93,.2,mid],[.08,.4,10],p.ceiling);
      for(let z=back+.9;z<front;z+=1.25){
        cuboid([side*6.88,3.5,z],[.24,6.7,.065],p.accent,1);
        cuboid([side*2.2,6.92,z],[.045,.03,.9],'#e5dfb7',3);
      }
      // Long benches sit outside the walking route.
      cuboid([side*3.7,.52,mid+1.2],[.65,.16,2.6],p.wall);
      for(const dz of [-.9,.9])cuboid([side*3.7,.24,mid+1.2+dz],[.44,.48,.18],p.ceiling);
    }
    // Framed field photographs remain objects mounted inside each room.
    cuboid([5.1,3.35,back+.48],[3.32,2.24,.18],p.ceiling);
    panel([[3.5,4.41,back+.58],[6.7,4.41,back+.58],[6.7,2.29,back+.58],[3.5,2.29,back+.58]],art[i]);
    cuboid([5.1,4.67,back+.79],[3.32,.04,.16],'#e9d9ad',3);
    // A restrained, angular installation gives every room a different silhouette.
    for(let j=0;j<5;j++){
      const x=-5.45+(j%2)*.75,z=mid-2.1+j*.8;
      const height=i===0?(.65+j*.22):i===1?(2.5+(j%3)*.8):i===2?(1.5+j*.32):(3.1+(j%2)*1.1);
      cuboid([x,height/2,z],[i===1?.16:.38,height,.32],i===2?'#8092b0':p.wall);
      cuboid([x,height+.025,z],[i===1?.17:.39,.025,.33],p.accent,3);
    }
    if(i===2)for(let j=0;j<38;j++){
      const x=-5.9+((j*47)%113)/113*11.8,z=back+.5+((j*31)%79)/79*9;
      cuboid([x,6.94,z],[.026,.02,.026],'#c7d7f1',3);
    }
  }
  // Each partition is assembled around an empty 3.4 × 4.9 metre aperture.
  for(const z of DOORS){
    const p=palettes[roomAt(z-.1)],x=routeX(z),edge=1.7;
    const left=x-edge,right=x+edge;
    cuboid([(-7+left)/2,3.5,z],[(left+7),7,.65],p.wall);
    cuboid([(right+7)/2,3.5,z],[(7-right),7,.65],p.wall);
    cuboid([x,5.95,z],[3.4,2.1,.65],p.wall);
    // Wide flat copper jambs, recessed dark reveal and thin luminous inside edge.
    for(const side of [-1,1]){
      cuboid([x+side*1.82,2.5,z],[.24,5,.87],'#aa9064',1);
      cuboid([x+side*1.705,2.45,z],[.025,4.9,.7],'#8d7857',1);
      cuboid([x+side*1.685,2.45,z+.345],[.018,4.9,.018],'#e7cf95',3);
      cuboid([x+side*2.10,2.65,z+.36],[.025,5.3,.06],p.accent,1);
    }
    cuboid([x,5,z],[3.88,.2,.87],'#aa9064',1);
    cuboid([x,4.91,z],[3.4,.025,.7],'#8d7857',1);
    cuboid([x,4.895,z+.345],[3.4,.018,.018],'#e7cf95',3);
    cuboid([x,.012,z],[3.4,.024,.87],'#b3a17c',1);
    // Floor light occupies world space and disappears behind the near plane.
    cuboid([x,.015,z+.95],[2.4,.016,.025],p.accent,3);
  }
  cuboid([0,3.5,10],[14,7,.25],'#405653');
  cuboid([0,3.15,9.8],[5.3,3.64,.1],'#304a54');
  panel([[2.55,4.85,9.73],[-2.55,4.85,9.73],[-2.55,1.45,9.73],[2.55,1.45,9.73]],art[0]);
  cuboid([0,3.5,-30],[14,7,.25],'#627981');
  cuboid([0,3.15,-29.8],[5.3,3.64,.1],'#304a54');
  panel([[-2.55,4.85,-29.73],[2.55,4.85,-29.73],[2.55,1.45,-29.73],[-2.55,1.45,-29.73]],art[3]);
  batches.unshift({vertices:solid});
  for(const batch of batches){
    batch.count=batch.vertices.length/12;
    batch.buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,batch.buffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(batch.vertices),gl.STATIC_DRAW);
    delete batch.vertices;
    if(batch.texture){
      const tex=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,tex);
      gl.texImage2D(gl.TEXTURE_2D,0,gl.RGB,gl.RGB,gl.UNSIGNED_BYTE,batch.texture);
      gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);batch.texture=tex;
    }
  }
  return {
    canvas,triangles:batches.reduce((sum,b)=>sum+b.count/3,0),
    render(width,height,eye,yaw){
      if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;gl.viewport(0,0,width,height);}
      gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.useProgram(program);
      gl.uniform3fv(uniforms.eye,eye);gl.uniform1f(uniforms.yaw,yaw);gl.uniform1f(uniforms.aspect,width/height);
      gl.uniform1f(uniforms.lens,1.48);gl.uniform1f(uniforms.offset,width/height>1.2?.24:0);
      gl.uniform1i(uniforms.artwork,0);
      for(const b of batches){
        gl.bindBuffer(gl.ARRAY_BUFFER,b.buffer);
        for(const [name,size,offset] of [['position',3,0],['normal',3,3],['color',3,6],['uv',2,9],['material',1,11]]){
          gl.enableVertexAttribArray(attributes[name]);gl.vertexAttribPointer(attributes[name],size,gl.FLOAT,false,48,offset*4);
        }
        gl.uniform1f(uniforms.textured,b.texture?1:0);
        if(b.texture)gl.bindTexture(gl.TEXTURE_2D,b.texture);
        gl.drawArrays(gl.TRIANGLES,0,b.count);
      }
    },
    dispose(){for(const b of batches){gl.deleteBuffer(b.buffer);if(b.texture)gl.deleteTexture(b.texture);}shaders.forEach(s=>gl.deleteShader(s));gl.deleteProgram(program);gl.getExtension('WEBGL_lose_context')?.loseContext();},
  };
}

import {clamp} from './math.mjs';

// Acceleration and braking use seconds/metres, independent of the display rate.
export function createTravel(initial){
  let z=initial,target=initial,velocity=0;
  return {
    get z(){return z;},get target(){return target;},get velocity(){return velocity;},
    get moving(){return Math.abs(target-z)>.0001;},
    go(next){target=next;},
    seek(next){z=target=next;velocity=0;},
    step(dt){
      if(dt<=0)return;
      // Substeps keep braking stable on slower frames and during deterministic replay.
      const count=Math.ceil(dt/.008),delta=dt/count;
      for(let i=0;i<count;i++){
        const distance=target-z;
        const desired=Math.sign(distance)*Math.min(2.6,Math.sqrt(2*2.2*Math.abs(distance)));
        velocity+=clamp(desired-velocity,-2.2*delta,2.2*delta);
        const step=velocity*delta;
        if(Math.abs(step)>=Math.abs(distance)&&step*distance>=0){z=target;velocity=0;}
        else z+=step;
      }
    },
  };
}

